from pathlib import Path
import csv,json,hashlib
ROOT=Path(__file__).resolve().parent
URL='https://www.cambridgema.gov/-/media/Files/Traffic/2021/20221118_northmassavepostimplementationanalysis.pdf'
WEB='https://www.cambridgema.gov/streetsandtransportation/projectsandprograms/massavedudleysttoalewifebrookpkwy'
def savecsv(name,rows):
 with (ROOT/name).open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
# Source-displayed means, not hidden unrounded values. Published difference/% cells sometimes differ because of rounding.
rows=[]
matrices=[
 ('2021_near_opening','Massachusetts Avenue','NB/SB',2,8,[[5.1,5.2,4.6,4.7],[5.6,5.3,6.0,6.2],[7.3,7.9,5.1,5.6],[5.4,5.9,4.9,5.3]]),
 ('2021_near_opening','Broadway','EB/WB',4,8,[[3.2,3.2,3.2,3.0],[4.4,4.3,3.5,3.5],[3.9,3.8,3.8,3.8],[3.7,3.8,3.6,3.4]]),
 ('2019_to_2022','Massachusetts Avenue','NB/SB',6,9,[[5.7,5.0,4.9,4.7],[6.9,5.2,6.6,6.4],[8.0,8.2,5.2,5.4],[5.9,5.5,5.0,5.1]]),
 ('2019_to_2022','Broadway','EB/WB',8,9,[[3.1,3.2,3.3,3.1],[4.5,4.1,3.7,3.4],[3.5,3.9,3.8,3.9],[3.6,3.7,3.6,3.4]])]
for window,road,dirs,table,page,vals in matrices:
 for period,v in zip(['full_day','07:00-09:00','16:00-18:00','09:00-16:00'],vals):
  for n,d in enumerate(dirs.split('/')):
   b,a=v[2*n:2*n+2]
   rows.append(dict(study_id='cambridge_mass_2021',window=window,road=road,role='treated' if road=='Massachusetts Avenue' else 'comparison',direction=d,day_type='Tue_Wed_Thu',period=period,before=b,after=a,unit='minutes',computed_change=round(a-b,4),computed_percent=round((a/b-1)*100,4),source_table=table,source_pdf_page=page,source_url=URL,precision_note='source inputs rounded to 0.1 minute; calculations are descriptive'))
savecsv('cambridge_road_times.csv',rows)
bus=[]
for direction,page,table,data in [('inbound',14,12,[('Magoun St','Cottage Park Ave',54,36,79,41,26,58),('Cottage Park Ave','Cedar St',42,30,66,31,22,36),('Cedar St','Norris St',55,39,72,44,29,56)]),('outbound',15,13,[('Cameron Ave','Churchill Ave',111,44,303,35,23,45),('Churchill Ave','Gladstone St',53,19,82,31,20,42),('Gladstone St','Route 16',56,21,89,39,14,72)])]:
 for origin,destination,b,bmin,bmax,a,amin,amax in data:
  bus.append(dict(study_id='cambridge_mass_2021',direction=direction,origin=origin,destination=destination,before_month='2019-05',after_month='2022-05',before=b,after=a,unit='seconds',computed_change=a-b,computed_percent=round((a/b-1)*100,4),before_min=bmin,before_max=bmax,after_min=amin,after_max=amax,source_table=table,source_pdf_page=page,source_url=URL,metric_note='average/minimum/maximum of time-of-day median bus-link runtimes; not door-to-door times; minima/maxima are not individual-trip tails'))
savecsv('cambridge_bus_times.csv',bus)
bikes=[]
for period,vals in [('AM_peak_hour',[('Mass Ave',243,267,10),('Cedar Street',5,2,-2),('Linear Park',138,138,0)]),('PM_peak_hour',[('Mass Ave',216,241,12),('Cedar Street',5,4,-20),('Linear Park',170,123,-28)])]:
 for road,b,a,pub in vals:
  bikes.append(dict(study_id='cambridge_mass_2021',road=road,period=period,before_month='2019-05',after_month='2022-05',before=b,after=a,unit='bicycles_in_peak_hour',computed_change=a-b,computed_percent=round((a/b-1)*100,4),source_printed_percent=pub,source_url=WEB,source_section='January 2023: Bike Ridership Data',quality_flag='Source percentage inconsistent with integer counts' if road=='Cedar Street' and period.startswith('AM') else ''))
savecsv('cambridge_bike_counts.csv',bikes)
C=[]
def add(**x):C.append(x)
